shellCommands.command:
node --input-type=module <<'EOF'
import assert from 'node:assert/strict'
const base = 'http://localhost:3100'
for (const [path, expected] of [
  ['/products/lamp?currency=EUR', ['Brass lamp', 'EUR 110.40', 'Stone vase']],
  ['/products/lamp', ['Brass lamp', 'USD 120.00', 'Stone vase']],
  ['/products/vase?currency=EUR', ['Stone vase', 'EUR 73.60', 'Brass lamp']],
]) {
  const response = await fetch(base + path)
  const html = await response.text()
  assert.equal(response.status, 200, path)
  for (const text of expected) assert.ok(html.includes(text), `${path}: missing ${text}`)
  console.log(`${path}: 200; ${expected.join(', ')}`)
}
const response = await fetch(base + '/products/missing')
assert.equal(response.status, 404)
console.log('/products/missing: 404')
const started = performance.now()
const streamed = await fetch(base + '/products/lamp?currency=EUR')
const reader = streamed.body.getReader()
let first = ''
while (!first.includes('Loading product details...')) {
  const chunk = await reader.read()
  assert.equal(chunk.done, false, 'no product fallback in response')
  first += new TextDecoder().decode(chunk.value)
}
assert.ok(first.includes('Signal Shop collection'))
assert.ok(!first.includes('Stone vase'), 'related product already in shell')
const firstMs = Math.round(performance.now() - started)
let rest = ''
while (true) {
  const chunk = await reader.read()
  if (chunk.done) break
  rest += new TextDecoder().decode(chunk.value)
}
assert.ok(rest.includes('Brass lamp') && rest.includes('Stone vase'))
console.log(`shell and product fallback in initial response (${firstMs}ms); product and related details streamed afterward`)
EOF

